import logo from './logo.svg';
import './App.css';
import {useState} from "react";

function App() {
    const [user, setUser] = useState({
        "id" : "",
        "name" : "",
        "pw" : "",

        "pw2": ""
    });

    const handleUserInfoChange = (e) => {
        setUser({
            ...user,
            [e.target.name] : e.target.value
        });
    }
    const signIn = () => {
        if(!isFormValid()) return false;
        fetch("/signin")
    }
    const signup = () => {
        if(!isFormValid()) return false;
        fetch("/signup")
    }
    const isFormValid = () => {
        const form = document.getElementById("");
        for(const key in user){
            if(user[key].length<1) {
                alert("Enter "+key);
                return false;
            }
        }
        return true;
    }

    return (
        <div className="App">
            <h1>MAIN</h1>
            <br/><br/><br/>
            <div style={{display: 'flex', justifyContent: 'center'}}>
                <div style={{width: '30%', textAlign: 'center'}}>
                    <h3>Sign up</h3>
                    Name: <input type={"text"} name={"name"} onChange={handleUserInfoChange}/><br/>
                    ID: <input type={"text"} name={"id"} onChange={handleUserInfoChange}/><br/>
                    PW: <input type={"text"} name={"pw"} onChange={handleUserInfoChange}/><br/><br/>
                    <button>submit</button>
                </div>
                <div style={{width: '30%', textAlign: 'center'}}>
                    <h3>Sign in</h3>
                    ID: <input type={"text"} name={"id"} onChange={handleUserInfoChange}/><br/>
                    PW: <input type={"text"} name={"pw"} onChange={handleUserInfoChange}/><br/><br/>
                    <button>submit</button>
                </div>
            </div>
        </div>
    );
}

export default App;
